<?php
defined('ABSPATH')||exit; class CFP_Order_Bump{public function hooks():void{add_action('woocommerce_review_order_before_submit',array($this,'render')); add_action('woocommerce_checkout_create_order_line_item',array($this,'mark'),10,4);} public function render():void{$product_id=(int)get_option('cfp_order_bump_product_id'); if(!$product_id) return; echo '<div class="cfp-order-bump"><label><input type="checkbox" name="cfp_order_bump" value="'.esc_attr($product_id).'"> '.esc_html__('Add this special offer to my order','conversionflow-pro').'</label></div>'; (new CFP_Tracking())->track('bump_view');} public function mark($item,$cart_item_key,$values,$order):void{ if(!empty($values['cfp_order_bump'])){$item->add_meta_data('_cfp_order_bump','yes',true);} }}
